import * as React from "react";

export type NavBarLink = {
  label: string;
  href: string;
  active?: boolean;
};

export type NavBarProps = {
  /** Brand/logo slot — an image + wordmark, or any custom mark. */
  brand: React.ReactNode;
  /** Where the brand mark links to. Defaults to "/". */
  brandHref?: string;
  /** Primary nav links, shown between the brand and the action slot. */
  links?: NavBarLink[];
  /** Right-aligned action slot — typically a `Button` or two. */
  actions?: React.ReactNode;
  className?: string;
};

/**
 * The site header: brand mark, primary nav links, and a right-aligned
 * action slot (sign-in / CTA buttons).
 *
 * @example
 * <NavBar
 *   brand={<><img src="/logo.png" width={28} height={28} alt="" /><span>Tikkitte</span></>}
 *   links={[
 *     { label: "Home", href: "/", active: true },
 *     { label: "Browse events", href: "/events" },
 *     { label: "Organizers", href: "/organizers" },
 *   ]}
 *   actions={<Button variant="primary" href="/signup">List your event</Button>}
 * />
 */
export function NavBar({ brand, brandHref = "/", links = [], actions, className }: NavBarProps) {
  return (
    <nav className={["tk-navbar", className ?? ""].filter(Boolean).join(" ")}>
      <a href={brandHref} className="tk-navbar__brand">
        {brand}
      </a>
      {links.length > 0 && (
        <ul className="tk-navbar__links">
          {links.map((link) => (
            <li key={link.href}>
              <a
                href={link.href}
                className={["tk-navbar__link", link.active ? "tk-navbar__link--active" : ""]
                  .filter(Boolean)
                  .join(" ")}
              >
                {link.label}
              </a>
            </li>
          ))}
        </ul>
      )}
      {actions && <div className="tk-navbar__actions">{actions}</div>}
    </nav>
  );
}
