import * as React from "react";

export type FooterColumn = {
  title: string;
  links: { label: string; href: string }[];
};

export type FooterProps = {
  /** Brand/logo slot at the top-left of the footer. */
  brand: React.ReactNode;
  /** Short tagline under the brand, e.g. "Event ticketing for Ghana." */
  tagline?: React.ReactNode;
  /** Link columns (Explore, Contact, etc.). */
  columns?: FooterColumn[];
  /** Legal line on the bottom-left, e.g. "© 2026 Company Ltd." */
  legalText: React.ReactNode;
  /** Bottom-right legal links (Terms, Privacy, Refunds). */
  legalLinks?: { label: string; href: string }[];
  className?: string;
};

/**
 * Site footer: brand + tagline, a row of link columns, and a bottom legal
 * line with secondary links.
 *
 * @example
 * <Footer
 *   brand={<span>Tikkitte</span>}
 *   tagline="Event ticketing for Ghana."
 *   columns={[
 *     { title: "Explore", links: [{ label: "Browse events", href: "/events" }, { label: "Sell tickets", href: "/organizers" }] },
 *     { title: "Contact", links: [{ label: "Contact us", href: "/contact" }] },
 *   ]}
 *   legalText="© 2026 FIRSTPASS EVENTS LTD."
 *   legalLinks={[{ label: "Terms", href: "/terms" }, { label: "Privacy", href: "/privacy" }]}
 * />
 */
export function Footer({ brand, tagline, columns = [], legalText, legalLinks = [], className }: FooterProps) {
  return (
    <footer className={["tk-footer", className ?? ""].filter(Boolean).join(" ")}>
      <div className="tk-footer__top">
        <div className="tk-footer__brand-col">
          {brand}
          {tagline && <p className="tk-footer__tagline">{tagline}</p>}
        </div>
        {columns.length > 0 && (
          <div className="tk-footer__columns">
            {columns.map((col) => (
              <div className="tk-footer__col" key={col.title}>
                <p className="tk-footer__col-title">{col.title}</p>
                {col.links.map((link) => (
                  <a key={link.href} href={link.href}>
                    {link.label}
                  </a>
                ))}
              </div>
            ))}
          </div>
        )}
      </div>
      <div className="tk-footer__legal">
        <p className="tk-footer__legal-text">{legalText}</p>
        {legalLinks.length > 0 && (
          <div className="tk-footer__legal-links">
            {legalLinks.map((link) => (
              <a key={link.href} href={link.href}>
                {link.label}
              </a>
            ))}
          </div>
        )}
      </div>
    </footer>
  );
}
