import * as React from "react";

export type EyebrowProps = React.ComponentPropsWithoutRef<"p">;

/**
 * Small uppercase label in the brand blue, set above a section heading
 * ("FOR ORGANIZERS", "GHANA'S EVENTS"). Plain text, no background.
 *
 * @example
 * <Eyebrow>For organizers</Eyebrow>
 */
export const Eyebrow = React.forwardRef<HTMLParagraphElement, EyebrowProps>(
  ({ className, children, ...props }, ref) => (
    <p ref={ref} className={["tk-eyebrow", className ?? ""].filter(Boolean).join(" ")} {...props}>
      {children}
    </p>
  )
);
Eyebrow.displayName = "Eyebrow";
